import { useState } from 'react'
import { Link } from '@tanstack/react-router'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ThreadCard } from '@/components/ants/thread-card'
import {
  Plus,
  Search,
  Filter,
  Pin,
  MessageSquare,
} from 'lucide-react'

// Mock thread data
const mockThreads = [
  {
    id: '1',
    title: 'Research quantum computing advances',
    lastMessage: 'Here\'s what I found about quantum error correction...',
    updatedAt: '2026-06-14T14:23:00Z',
    runCount: 3,
    isPinned: true,
    isActive: true,
  },
  {
    id: '2',
    title: 'Write documentation for auth module',
    lastMessage: 'Done! 3 files created.',
    updatedAt: '2026-06-14T13:45:00Z',
    runCount: 5,
    isPinned: false,
    isActive: false,
  },
  {
    id: '3',
    title: 'Analyze competitor pricing',
    lastMessage: 'Waiting for response...',
    updatedAt: '2026-06-14T12:30:00Z',
    runCount: 2,
    isPinned: false,
    isActive: false,
  },
]

export function ThreadsPage() {
  const [search, setSearch] = useState('')

  const filteredThreads = mockThreads.filter((t) =>
    t.title.toLowerCase().includes(search.toLowerCase())
  )

  const pinned = filteredThreads.filter((t) => t.isPinned)
  const active = filteredThreads.filter((t) => !t.isPinned)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-heading-lg text-text-primary">Threads</h1>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm">
            <Filter className="mr-2 h-4 w-4" />
            Filter
          </Button>
          <Link to="/">
            <Button size="sm">
              <Plus className="mr-2 h-4 w-4" />
              New Thread
            </Button>
          </Link>
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-tertiary" />
        <Input
          placeholder="Search threads..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="pl-10"
        />
      </div>

      {/* Pinned threads */}
      {pinned.length > 0 && (
        <section>
          <h2 className="mb-3 flex items-center gap-2 text-heading-sm text-text-secondary">
            <Pin className="h-3.5 w-3.5" />
            Pinned
          </h2>
          <div className="space-y-2">
            {pinned.map((thread) => (
              <Link key={thread.id} to="/threads/$threadId" params={{ threadId: thread.id }}>
                <ThreadCard thread={thread} />
              </Link>
            ))}
          </div>
        </section>
      )}

      {/* Active threads */}
      <section>
        <h2 className="mb-3 flex items-center gap-2 text-heading-sm text-text-secondary">
          <MessageSquare className="h-3.5 w-3.5" />
          Recent
        </h2>
        <div className="space-y-2">
          {active.map((thread) => (
            <Link key={thread.id} to="/threads/$threadId" params={{ threadId: thread.id }}>
              <ThreadCard thread={thread} />
            </Link>
          ))}
        </div>
      </section>
    </div>
  )
}
